```c
#include <stdio.h>
#include <stdbool.h>
#include <string.h>

#define MAXN 40

int L, C, P;
int board[8][8]; // 0: empty, 1: black
int is_candidate[8][8];
int id[8][8];
int num_candidates;

// Graph for bipartite matching
int head[MAXN], to[MAXN * 4], nxt[MAXN * 4], edge_count;
int match[MAXN];
bool visited[MAXN];

void add_edge(int u, int v) {
    to[edge_count] = v;
    nxt[edge_count] = head[u];
    head[u] = edge_count++;
}

bool dfs(int u) {
    for (int e = head[u]; e != -1; e = nxt[e]) {
        int v = to[e];
        if (!visited[v]) {
            visited[v] = true;
            if (match[v] < 0 || dfs(match[v])) {
                match[v] = u;
                return true;
            }
        }
    }
    return false;
}

int main(void) {
    if (scanf("%d %d", &L, &C) != 2) return 0;
    if (scanf("%d", &P) != 1) return 0;

    memset(board, 0, sizeof(board));
    for (int i = 0; i < P; i++) {
        int r, c;
        scanf("%d %d", &r, &c);
        board[r][c] = 1; // black piece
    }

    const int dr[] = {-1, 1, 0, 0};
    const int dc[] = {0, 0, -1, 1};

    num_candidates = 0;
    memset(is_candidate, 0, sizeof(is_candidate));

    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (board[r][c] == 1) continue;

            bool adj_black = false;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr >= 1 && nr <= L && nc >= 1 && nc <= C) {
                    if (board[nr][nc] == 1) {
                        adj_black = true;
                        break;
                    }
                }
            }

            if (adj_black) {
                is_candidate[r][c] = 1;
                id[r][c] = num_candidates++;
            }
        }
    }

    memset(head, -1, sizeof(head));
    edge_count = 0;

    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (!is_candidate[r][c]) continue;
            // Only add edges from even parity cells to odd parity cells
            if ((r + c) % 2 == 0) {
                int u = id[r][c];
                for (int d = 0; d < 4; d++) {
                    int nr = r + dr[d];
                    int nc = c + dc[d];
                    if (nr >= 1 && nr <= L && nc >= 1 && nc <= C) {
                        if (is_candidate[nr][nc]) {
                            int v = id[nr][nc];
                            add_edge(u, v);
                        }
                    }
                }
            }
        }
    }

    memset(match, -1, sizeof(match));
    int max_matching = 0;

    for (int r = 1; r <= L; r++) {
        for (int c = 1; c <= C; c++) {
            if (is_candidate[r][c] && (r + c) % 2 == 0) {
                int u = id[r][c];
                memset(visited, false, sizeof(visited));
                if (dfs(u)) {
                    max_matching++;
                }
            }
        }
    }

    int max_independent_set = num_candidates - max_matching;
    printf("%d\n", max_independent_set);

    return 0;
}
```

